async function allRows(factory){let result=[];for(let offset=0;;offset+=500){const rows=await checked(factory().range(offset,offset+499));result.push(...rows);if(rows.length<500)return result}}
function uniqueCompleted(items){const seen=new Set();return items.filter(i=>{const key=i.day+':'+i.taskId;if(seen.has(key))return false;seen.add(key);return true}).sort((a,b)=>a.day.localeCompare(b.day)||String(a.title).localeCompare(String(b.title),'fa'))}
function reportHeading(report){const month=s=>new Intl.DateTimeFormat('fa-IR',{month:'long',timeZone:'UTC'}).format(new Date(s+'T12:00:00Z'));const year=s=>new Intl.DateTimeFormat('fa-IR',{year:'numeric',timeZone:'UTC'}).format(new Date(s+'T12:00:00Z'));const sameMonth=month(report.from)===month(report.to)&&year(report.from)===year(report.to);if(report.type==='monthly'&&sameMonth)return 'گزارش ماهیانه '+month(report.from)+'ماه '+year(report.from);return (report.type==='weekly'?'گزارش هفتگی':'گزارش ماهیانه')}
function table(report){const items=uniqueCompleted(report.items),groups=new Map();for(const i of items){if(!groups.has(i.day))groups.set(i.day,[]);groups.get(i.day).push(i)}return '<article class="own-report-paper"><header class="brief-report-header"><div class="brief-company"><img src="'+new URL('samandis.jpg',location.href).href+'" alt="سمندیس"><span>شرکت سمندیس</span></div><div class="brief-heading"><h1>'+reportHeading(report)+'</h1><h2>'+escape(report.name)+'</h2><p>'+escape(report.project)+'</p></div></header><div class="brief-period"><span>بازهٔ گزارش</span><b>'+fmt(report.from)+' تا '+fmt(report.to)+'</b></div><table class="brief-table"><colgroup><col style="width:24%"><col style="width:76%"></colgroup><thead><tr><th>روز انجام</th><th>خلاصهٔ فعالیت‌ها</th></tr></thead><tbody>'+[...groups].map(([day,entries])=>'<tr><td class="brief-date"><b>'+fmt(day)+'</b><small>'+new Intl.DateTimeFormat('fa-IR',{weekday:'long',timeZone:'UTC'}).format(new Date(day+'T12:00:00Z'))+'</small></td><td><ul>'+entries.map(i=>'<li>'+escape(i.title)+'</li>').join('')+'</ul></td></tr>').join('')+(items.length?'':'<tr><td colspan="2" class="brief-empty">—</td></tr>')+'</tbody></table></article>'}
const paperCss=window.SAMANDIS_WORK_PAPER_CSS||'';
function htmlReport(){return '<!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><title>گزارش کار '+escape(lastReport.name)+'</title><style>'+paperCss+'</style><body class="work-report-export">'+table(lastReport)+'</body></html>'}
function print(){if(!lastReport)return;const frame=document.createElement('iframe');frame.className='own-report-print-frame';frame.title='چاپ گزارش شخصی';frame.onload=()=>{Promise.all([frame.contentDocument.fonts?.ready,...[...frame.contentDocument.images].map(img=>img.complete?Promise.resolve():new Promise(resolve=>{img.onload=img.onerror=resolve}))]).then(()=>{frame.contentWindow.focus();frame.contentWindow.print()})};frame.srcdoc=htmlReport();document.querySelector('.own-report-print-frame')?.remove();document.body.append(frame)}
function download(){if(!lastReport)return;const blob=new Blob(['\ufeff'+htmlReport()],{type:'text/html;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='گزارش-کار-'+lastReport.from+'-'+lastReport.to+'.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function load(){const token=++generation,host=q(shared?'#sharedContent':'#workspace'),uid=shared?session?.user.id:me(),pid=shared?project?.id:'demo',memberId=shared?mine()?.id:me();if(!host||shared&&!memberId)return;lastReport=null;host.innerHTML='<section class="own-report"><h1>گزارش کار من</h1><p class="shared-meta">کارهایی که خودتان تیک انجامشان را زده‌اید، بر اساس روز ثبت انجام.</p><form id="ownReportRange" class="range-controls"><label>نوع گزارش<select name="reportType" id="ownReportType"><option value="monthly" '+(reportType==='monthly'?'selected':'')+'>ماهیانه</option><option value="weekly" '+(reportType==='weekly'?'selected':'')+'>هفتگی</option></select></label><label>از تاریخ<input type="date" name="from" value="'+from+'" required></label><label>تا تاریخ<input type="date" name="to" value="'+to+'" required></label><button class="primary">تهیه گزارش</button></form><div class="own-report-actions"><button id="ownReportPrint" class="primary" disabled>چاپ / ذخیره PDF</button><button id="ownReportDownload" class="secondary" disabled>دریافت گزارش</button></div><div id="ownReportBody" aria-live="polite">در حال تهیه گزارش…</div></section>';q('#ownReportRange').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),a=f.get('from'),b=f.get('to');if(!a||!b||a>b)return(shared?message:toast)('بازهٔ تاریخ معتبر نیست.');reportType=f.get('reportType');from=a;to=b;load()};q('#ownReportType').onchange=e=>{reportType=e.target.value;to=today();if(reportType==='weekly'){const d=new Date(to+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-(d.getUTCDay()+1)%7);from=d.toISOString().slice(0,10)}else{from=SamandisDates.parse(SamandisDates.display(to).split('/').slice(0,2).join('/')+'/1')}load()};q('#ownReportPrint').onclick=print;q('#ownReportDownload').onclick=download;const a=from,b=to;
try{let items=[];if(shared){const end=new Date(b+'T12:00:00Z');end.setUTCDate(end.getUTCDate()+1);const upper=end.toISOString().slice(0,10)+'T00:00:00+03:30';const events=await allRows(()=>db.from('sm_events').select('*,task:sm_tasks(title,description)').eq('project_id',pid).eq('actor_id',memberId).eq('kind','submit').gte('created_at',a+'T00:00:00+03:30').lt('created_at',upper).order('created_at'));items=events.map(e=>({day:dayKey(e.created_at),taskId:e.task_id,title:e.payload?.before?.title||e.task?.title||'کار',text:e.payload?.before?.description??e.task?.description??''}))}else{items=tasks.flatMap(t=>(t.submissions||[]).filter(x=>x.by===memberId&&dayKey(x.at)>=a&&dayKey(x.at)<=b).map(x=>({day:dayKey(x.at),taskId:t.id,title:t.title,text:x.description||t.description||''})))}if(token!==generation||(shared?(scope!==key||session?.user.id!==uid||project?.id!==pid):view!==key))return;lastReport={uid,pid,name:shared?mine().name:people[me()],project:shared?project.name:'پروژه دارایی',from:a,to:b,items:uniqueCompleted(items),type:reportType};q('#ownReportBody').innerHTML=table(lastReport);q('#ownReportPrint').disabled=false;q('#ownReportDownload').disabled=false}catch(e){if(token===generation&&q('#ownReportBody'))q('#ownReportBody').textContent=shared?failure(e):e.message}}
const oldRender=render;render=function(...args){const active=(shared?scope:view)===key;if(active&&lastReport&&lastReport.uid===(shared?session?.user.id:me())&&lastReport.pid===(shared?project?.id:'demo')&&q('#ownReportBody'))return;if(!shared&&active){view='mine';try{oldRender(...args)}finally{view=key}}else oldRender(...args);button.classList.toggle('active',active);if(active){document.querySelectorAll('[data-desk-view]').forEach(b=>b.classList.remove('active'));q('#deskCrumb').textContent='گزارش کار من';load()}else{generation++;lastReport=null}};
